\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/2/\",\"title\":\"Chapter Two: Contents of the Gītā Summarized\"}],\"url_path\":\"/en/library/bg/2/28/\",\"bb\":590,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/2/27/\",\"title\":\"TEXT 27\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/2/29/\",\"title\":\"TEXT 29\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":652,\"bb\":567952,\"url_path\":\"/en/library/bg/2/28/devanagari/\",\"body_final\":\"अव्यक्तादीनि भूतानि व्यक्तमध्यानि भारत ।
अव्यक्तनिधनान्येव तत्र का परिदेवना ॥ २८ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":653,\"bb\":591,\"url_path\":\"/en/library/bg/2/28/b591/\",\"body_value\":\"avyaktādīni bhūtāni
vyakta-madhyāni bhārata
avyakta-nidhanāny eva
tatra kā paridevanā\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":654,\"bb\":592,\"url_path\":\"/en/library/bg/2/28/b592/\",\"shadow_value\":\"avyakta-ādīni – in the beginning unmanifested; bhūtāni – all that are created; vyakta – manifested; madhyāni – in the middle; bhārata – O descendant of Bharata; avyakta – nonmanifested; nidhanāni – when vanquished; eva – it is all like that; tatra – therefore; kā – what; paridevanā – lamentation.\",\"word_for_word_value\":[{\"word\":\"avyakta-ādīni\",\"translation\":\"in the beginning unmanifested\"},{\"word\":\"bhūtāni\",\"translation\":\"all that are created\"},{\"word\":\"vyakta\",\"translation\":\"manifested\"},{\"word\":\"madhyāni\",\"translation\":\"in the middle\"},{\"word\":\"bhārata\",\"translation\":\"O descendant of Bharata\"},{\"word\":\"avyakta\",\"translation\":\"nonmanifested\"},{\"word\":\"nidhanāni\",\"translation\":\"when vanquished\"},{\"word\":\"eva\",\"translation\":\"it is all like that\"},{\"word\":\"tatra\",\"translation\":\"therefore\"},{\"word\":\"kā\",\"translation\":\"what\"},{\"word\":\"paridevanā\",\"translation\":\"lamentation\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":655,\"bb\":593,\"url_path\":\"/en/library/bg/2/28/b593/\",\"body_value\":\"All created beings are unmanifest in their beginning, manifest in their interim state, and unmanifest again when annihilated. So what need is there for lamentation?\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":656,\"bb\":594,\"url_path\":\"/en/library/bg/2/28/b594/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":657,\"bb\":595,\"url_path\":\"/en/library/bg/2/28/b595/\",\"body_value\":\"And if we accept the Vedic conclusion as stated in the Bhagavad-gītā that these material bodies are perishable in due course of time (antavanta ime dehāḥ) but that the soul is eternal (nityasyoktāḥ śarīriṇaḥ), then we must remember always that the body is like a dress; therefore why lament the changing of a dress? The material body has no factual existence in relation to the eternal soul. It is something like a dream. In a dream we may think of flying in the sky, or sitting on a chariot as a king, but when we wake up we can see that we are neither in the sky nor seated on the chariot. The Vedic wisdom encourages self-realization on the basis of the nonexistence of the material body. Therefore, in either case, whether one believes in the existence of the soul or one does not believe in the existence of the soul, there is no cause for lamentation for loss of the body.\"}]}],\"short_title\":\"Bg. 2.28\",\"medium_title\":\"Bhagavad-gītā As It Is 2.28\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n26:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{